import hmac
import json


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""
    try:
        raw_body_str = raw_body.decode('utf-8')
        data = json.loads(raw_body_str)
    except (json.JSONDecodeError, UnicodeDecodeError):
        raise InvalidNotification("Invalid JSON")

    # Validate required fields
    if not isinstance(data, dict):
        raise InvalidNotification("Expecting JSON object")

    event_id = data.get('event_id')
    account_id = data.get('account_id')
    amount_minor = data.get('amount_minor')
    currency = data.get('currency')

    if not event_id or not isinstance(event_id, str):
        raise InvalidNotification("Missing or invalid event_id")
    if not account_id or not isinstance(account_id, str):
        raise InvalidNotification("Missing or invalid account_id")
    if not isinstance(amount_minor, int) or isinstance(amount_minor, bool):
        raise InvalidNotification("Invalid amount_minor")
    if not isinstance(currency, str) or len(currency) != 3:
        raise InvalidNotification("Invalid currency")
    for ch in currency:
        if not (ch >= 'A' and ch <= 'Z'):
            raise InvalidNotification("Invalid currency characters")

    # Validate timestamp
    ts_header = headers.get('X-Pay-Timestamp')
    if not ts_header:
        raise InvalidNotification("Missing X-Pay-Timestamp header")

    try:
        ts = int(ts_header)
    except (ValueError, TypeError):
        raise InvalidNotification("Invalid X-Pay-Timestamp")

    if abs(ts - now) > 300:
        raise InvalidNotification("Stale delivery")

    # Verify signature
    sig_header = headers.get('X-Pay-Signature')
    if not sig_header:
        raise InvalidNotification("Missing X-Pay-Signature header")

    prefix = "v1="
    if not sig_header.startswith(prefix):
        raise InvalidNotification("Invalid X-Pay-Signature format")

    expected_digest = hmac.new(
        secret,
        ts_header.encode('ascii') + b"." + raw_body.encode('ascii'),
        hashlib.sha256
    ).hexdigest()

    provided_digest = sig_header[len(prefix):]
    if not hmac.compare_digest(expected_digest, provided_digest):
        raise InvalidNotification("Invalid signature")

    return {
        'event_id': event_id,
        'account_id': account_id,
        'amount_minor': amount_minor,
        'currency': currency
    }"}

